// Hand-written TypeScript material with no Rust source, plus small helper
// functions/consts that used to live inline in the 6 files now generated by
// crates/athenaeum-core/src/ts_export.rs (see .superpowers/sdd/p1-ts-inventory.md
// for the full TS-ONLY classification — 68 declarations, all relocated here).
//
// Also carries `...Values` companion objects for former TS `enum`s that are
// referenced as VALUES elsewhere in the frontend (`ImageType`, `MatchMode`,
// `MasterPreference`) — ts-rs derives string-literal unions, not TS enums, so
// there is no runtime object to reference (`ImageType.Light` no longer
// exists; use `ImageTypeValues.Light`). Values are copied verbatim from the
// generated unions in ./models and ./calibration-config, not from memory.
//
// Import direction is one-way: this file imports types FROM the generated
// files below, never the reverse.

import type {
  ImageType,
  FramesSet,
  ScanRoot,
  CalendarMonthData,
} from './models';
import type { ArchiveCompression, FrameRole } from './archive';
import type { MatchMode, ParameterConfig, MasterPreference } from './calibration-config';
import type { AutofindStatus } from './plate-solve';
import type { AnnotationSettings } from './analysis-config';

