/** Progress event emitted during a master build (`master-build-progress`).
 *  `stage` documents the full backend contract including `'reading'`
 *  (reserved for future use — member-path enumeration is cheap enough today
 *  not to need its own tick, so the backend never actually emits it; see
 *  `athenaeum-core/src/api/masters.rs`'s `MasterBuildProgressEvent` doc
 *  comment). Consumers must not assume every listed stage will arrive. */
export interface MasterBuildProgressEvent {
  set_id: number;
  stage: 'reading' | 'integrating' | 'writing' | 'registering';
  current: number;
  total: number;
  percent: number;
  /** Bytes of source read so far / in total. `current`/`total` count bands,
   *  which say nothing about size once bands are machine-sized. */
  bytes_done: number;
  bytes_total: number;
}

/** Completion event for a master build (`master-build-complete`). ALWAYS
 *  emitted exactly once per `start_master_build` call regardless of outcome
 *  (success, error, cancelled). `set_id` is the SOURCE calibration set id,
 *  not `master_set_id` — see the Rust doc comment for why (rebuild keys off
 *  the same source set).
 *
 *  `warning` is the non-fatal counterpart of `error`: the build succeeded but
 *  the source data had something worth reporting (today: non-finite samples
 *  excluded from the integration). Optional because the hook also synthesizes
 *  local failure events that never carry one. */
export interface MasterBuildCompleteEvent {
  set_id: number;
  master_set_id: number | null;
  success: boolean;
  cancelled: boolean;
  error: string | null;
  warning?: string | null;
}

/** Registration status for a single frame. Note: the generated
 *  `RegistrationRecord.status` / `StackingPrepProgressEvent.status` fields
 *  are plain `string` (Rust field type is `String`, not an enum), so this
 *  narrower literal union is no longer structurally enforced there — kept
 *  here for call sites that still want the documented value set. */
export type FrameRegistrationStatus =
  | 'pending'
  | 'aligning'
  | 'aligned'
  | 'aligned_flipped'
  | 'reference'
  | 'failed';

/** Response from `compute_flat_contour_plot`. The `pixelsB64` field is the
 *  final 8-bit grayscale display image (length == width*height) base64-
 *  encoded for JSON transport. The frontend paints those bytes directly
 *  via putImageData; the legend strip is built from `minQuantile`,
 *  `maxQuantile`, and `contours`. */
export interface FlatContourPlot {
  width: number;
  height: number;
  /** Raw-units peak of the resampled, pre-rescale image. */
  peak: number;
  /** Raw-units mean. */
  mean: number;
  /** Raw-units min. */
  min: number;
  /** 1st-percentile sample value (legend low edge, original flat units). */
  minQuantile: number;
  /** 99th-percentile sample value (legend high edge, original flat units). */
  maxQuantile: number;
  /** Echoed back from the request — number of bands the result uses. */
  contours: number;
  /** Base64-encoded 8-bit grayscale buffer. */
  pixelsB64: string;
}

